+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * <p>A customer matches when every whitespace-separated term of {@code name}
+ * appears in its first or last name (ignoring case and accents), and, if any
+ * statuses are given, its status is one of them.
+ *
+ * @param name     free text; blank matches every customer
+ * @param statuses statuses to keep; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The normalized name terms, all of which must match. */
+    public List<String> terms() {
+        String normalized = normalize(name);
+        return normalized.isBlank()
+                ? List.of()
+                : Arrays.asList(WHITESPACE.split(normalized.strip()));
+    }
+
+    public boolean test(Customer customer) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        List<String> terms = terms();
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    /** Lower-cases and strips accents, so that {@code Mäkinen} becomes {@code makinen}. */
+    public static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
