+                        + "  window.dispatchEvent(new CustomEvent('vaadin-navigate',"
+                        + "    { detail: { state: null, url: $0, replace: true, callback: false } }));"
+                        + "} else {"
+                        + "  window.history.replaceState(window.history.state, '',"
+                        + "    new URL($0, document.baseURI).href);"
+                        + "}",
+                url, isReactRouterEnabled());
+    }
+
+    private static boolean isReactRouterEnabled() {
+        UI ui = UI.getCurrent();
+        return ui != null && ui.getSession() != null
+                && ui.getSession().getService().getDeploymentConfiguration().isReactEnabled();
+    }
+
+    /**
+     * The view's URL for a filter, relative to the application root, e.g.
+     * {@code ?name=vir&status=ACTIVE,CLOSED}; empty for the empty filter.
+     */
+    static String toUrl(CustomerFilter filter) {
+        List<String> parameters = new ArrayList<>();
+        if (!filter.name().isEmpty()) {
+            parameters.add(NAME_PARAMETER + "="
+                    + URLEncoder.encode(filter.name(), StandardCharsets.UTF_8).replace("+", "%20"));
+        }
+        if (!filter.statuses().isEmpty()) {
+            parameters.add(STATUS_PARAMETER + "=" + EnumSet.copyOf(filter.statuses()).stream()
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(",")));
+        }
+        return parameters.isEmpty() ? "" : "?" + String.join("&", parameters);
+    }
+
+    static Set<CustomerStatus> parseStatuses(String value) {
+        return Arrays.stream(value.split(","))
+                .map(String::strip)
+                .filter(name -> !name.isEmpty())
+                .map(name -> Arrays.stream(CustomerStatus.values())
+                        .filter(status -> status.name().equals(name.toUpperCase(Locale.ROOT)))
+                        .findFirst()
+                        .orElse(null))
+                .filter(Objects::nonNull)
+                .collect(Collectors.toCollection(() -> EnumSet.noneOf(CustomerStatus.class)));
     }

