+/** Drives the running application in a real, headless Chromium. */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserTest {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    private Page page;
+
+    @BeforeAll
+    static void startBrowser() {
+        playwright = Playwright.create(new Playwright.CreateOptions()
+                .setEnv(Map.of("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")));
+        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true));
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @BeforeEach
+    void openPage() {
+        page = browser.newPage();
+        page.setDefaultTimeout(60_000);
+    }
+
+    @AfterEach
+    void closePage() {
+        page.close();
+    }
+
+    private Locator summary() {
+        return page.getByText(java.util.regex.Pattern.compile("^Showing \\d+ of 500$"));
+    }
+
+    @Test
+    void typingFiltersWithFewQueriesAndUpdatesUrl() {
+        page.navigate("http://localhost:" + port + "/");
+        PlaywrightAssertions.assertThat(summary()).hasText("Showing 500 of 500");
+        page.waitForTimeout(1000);
+        queryLog.clear();
+
+        Locator input = page.locator("vaadin-text-field input");
+        input.pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(60));
+        page.waitForTimeout(1500);
+
+        System.out.println("URL after typing: " + page.url());
+        System.out.println("Pages: " + queryLog.pageQueries() + " counts: " + queryLog.countQueries());
+        assertTrue(page.url().endsWith("/?name=virtanen"), page.url());
+        assertTrue(queryLog.countQueries().size() <= 2, queryLog.countQueries().toString());
+        assertTrue(queryLog.pageQueries().size() <= 2, queryLog.pageQueries().toString());
+        PlaywrightAssertions.assertThat(summary())
+                .hasText("Showing " + queryLog.countQueries().getLast() + " of 500");
+
+        int historyLength = ((Number) page.evaluate("history.length")).intValue();
+        input.fill("");
+        page.waitForTimeout(1500);
+        System.out.println("URL after clearing: " + page.url());
+        assertEquals("http://localhost:" + port + "/", page.url());
+        assertEquals(historyLength, ((Number) page.evaluate("history.length")).intValue());
+        PlaywrightAssertions.assertThat(summary()).hasText("Showing 500 of 500");
+    }
+
+    @Test
+    void openingAUrlAppliesTheFilter() {
+        page.navigate("http://localhost:" + port + "/?name=vir&status=ACTIVE,CLOSED");
+        PlaywrightAssertions.assertThat(page.locator("vaadin-text-field input")).hasValue("vir");
+        PlaywrightAssertions.assertThat(summary()).not().hasText("Showing 500 of 500");
+        System.out.println("Summary: " + summary().textContent() + " URL: " + page.url());
+        assertFalse(page.locator("vaadin-multi-select-combo-box-chip").all().isEmpty());
+
+        page.locator("vaadin-text-field input").fill("");
+        page.waitForTimeout(1500);
+        System.out.println("URL after clearing name: " + page.url());
+        assertTrue(page.url().endsWith("/?status=ACTIVE,CLOSED"), page.url());
+    }
+}
